import{_ as a,c as r,o as t,ag as i}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Training Event Survey","description":"","frontmatter":{"title":"Training Event Survey"},"headers":[],"relativePath":"ai-ml/training-event-survey.md","filePath":"ai-ml/training-event-survey.md","lastUpdated":null}'),n={name:"ai-ml/training-event-survey.md"};function o(s,e,l,u,d,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="training-event-survey" tabindex="-1">Training Event Survey <a class="header-anchor" href="#training-event-survey" aria-label="Permalink to &quot;Training Event Survey&quot;">​</a></h1><h2 id="training-event-survey-workflow-guide" tabindex="-1">Training Event Survey Workflow Guide <a class="header-anchor" href="#training-event-survey-workflow-guide" aria-label="Permalink to &quot;Training Event Survey Workflow Guide&quot;">​</a></h2><h3 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>This guide outlines the workflow for creating surveys to gather baseline data, receive local expertise, and poll participants before, during, and after training events with partners. Effective surveys can enhance training effectiveness and foster collaboration.</p><h3 id="steps-to-create-surveys" tabindex="-1">Steps to Create Surveys <a class="header-anchor" href="#steps-to-create-surveys" aria-label="Permalink to &quot;Steps to Create Surveys&quot;">​</a></h3><h3 id="_1-define-objectives" tabindex="-1">1. Define Objectives <a class="header-anchor" href="#_1-define-objectives" aria-label="Permalink to &quot;1. Define Objectives&quot;">​</a></h3><ul><li>Identify the purpose of the survey: <ul><li>Collect baseline data about participants&#39; knowledge or skills.</li><li>Gather feedback on training content and delivery.</li><li>Assess local expertise and perspectives.</li></ul></li></ul><h3 id="_2-determine-survey-timing" tabindex="-1">2. Determine Survey Timing <a class="header-anchor" href="#_2-determine-survey-timing" aria-label="Permalink to &quot;2. Determine Survey Timing&quot;">​</a></h3><p>*<strong>Before Training</strong>: Establish baseline data to measure knowledge or skills. *<strong>During Training</strong>: Gather immediate feedback on content relevance and effectiveness. *<strong>After Training</strong>: Evaluate overall training impact and areas for improvement.</p><h3 id="_3-types-of-questions-to-create" tabindex="-1">3. Types of Questions to Create <a class="header-anchor" href="#_3-types-of-questions-to-create" aria-label="Permalink to &quot;3. Types of Questions to Create&quot;">​</a></h3><p>*<strong>Multiple Choice</strong>: Allow for quick responses and easy analysis. *<strong>Rating Scales</strong>: Gauge satisfaction or understanding on a scale (e.g., 1 to 5). *<strong>Open-Ended</strong>: Collect qualitative feedback and insights. *<strong>Yes/No</strong>: Simplify responses for specific inquiries.</p><h3 id="_4-choose-survey-platforms" tabindex="-1">4. Choose Survey Platforms <a class="header-anchor" href="#_4-choose-survey-platforms" aria-label="Permalink to &quot;4. Choose Survey Platforms&quot;">​</a></h3><p>*<strong>CryptPad</strong>: A secure, end-to-end encrypted collaborative platform that does not require a login, allowing participants to respond anonymously. <a href="https://cryptpad.fr" target="_blank" rel="noreferrer">CryptPad</a></p><ul><li>No Login Required to Create</li><li>No Login Required to Participate</li><li>Free</li><li>End-to-End Encrypted (Server can&#39;t see your data) <em><strong>Army 365</strong>: Forms can be made available to the public, and the DoD protects and serves the form. [</em>* Login is Required to Create</li><li>No Login Required to Participate</li><li>Free</li><li>.mil in URL *<strong>Google Forms</strong>: User-friendly and integrates easily with Google Sheets for data analysis. <a href="https://forms.osi.apps.mil/%5D" target="_blank" rel="noreferrer">https://forms.google.com Google Forms</a></li><li>Login is Required to Create</li><li>No Login Required to Participate</li><li>Free</li></ul><h3 id="_5-distribute-surveys" tabindex="-1">5. Distribute Surveys <a class="header-anchor" href="#_5-distribute-surveys" aria-label="Permalink to &quot;5. Distribute Surveys&quot;">​</a></h3><ul><li><p>Share links to the surveys via email, messaging apps, or training platforms.</p></li><li><p>Generate QR codes to distribute surveys easily using services like <a href="https://www.qrstuff.com" target="_blank" rel="noreferrer">QRStuff</a> or <a href="https://www.qr-code-generator.com" target="_blank" rel="noreferrer">QR Code Generator</a>.</p></li><li><p>Ensure instructions are clear and emphasize the importance of participation.</p></li></ul><h3 id="data-analysis" tabindex="-1">Data Analysis <a class="header-anchor" href="#data-analysis" aria-label="Permalink to &quot;Data Analysis&quot;">​</a></h3><h3 id="_6-collect-responses" tabindex="-1">6. Collect Responses <a class="header-anchor" href="#_6-collect-responses" aria-label="Permalink to &quot;6. Collect Responses&quot;">​</a></h3><ul><li>Monitor response rates and send reminders as necessary to improve participation.</li></ul><h3 id="_7-export-data" tabindex="-1">7. Export Data <a class="header-anchor" href="#_7-export-data" aria-label="Permalink to &quot;7. Export Data&quot;">​</a></h3><ul><li><p>Export survey results to Excel for further analysis.</p></li><li><p>Most platforms allow you to download data in CSV or XLSX formats.</p></li></ul><h3 id="_8-analyze-data-in-excel" tabindex="-1">8. Analyze Data in Excel <a class="header-anchor" href="#_8-analyze-data-in-excel" aria-label="Permalink to &quot;8. Analyze Data in Excel&quot;">​</a></h3><ul><li><p>Use functions such as:</p><ul><li>AVERAGE: To calculate average ratings.</li><li>COUNTIF: To count specific responses.</li><li>Pivot Tables: To summarize data and analyze trends.</li></ul></li><li><p>Create charts and graphs to visualize key findings.</p></li><li><p>Compare pre- and post-training results to assess impact.</p></li></ul><h3 id="_9-report-findings" tabindex="-1">9. Report Findings <a class="header-anchor" href="#_9-report-findings" aria-label="Permalink to &quot;9. Report Findings&quot;">​</a></h3><ul><li><p>Compile insights and recommendations based on the survey data.</p></li><li><p>Share findings with stakeholders to inform future training and collaborations.</p></li></ul><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>Creating effective surveys before, during, and after training events is crucial for understanding participant needs, gathering valuable feedback, and continuously improving training programs. [Up]</p><p>[Collection]</p>',28)])])}const g=a(n,[["render",o]]);export{h as __pageData,g as default};
